<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>Daily Tasks</title>

<style>
  :root {
    --bg: #f5f7fb;
    --surface: #ffffff;
    --text: #172033;
    --muted: #8992a5;
    --line: #e8ebf2;
    --accent: #6c5ce7;
    --green: #21b573;
    --shadow: 0 12px 35px rgba(30, 38, 60, .08);
  }

  * {
    box-sizing: border-box;
  }

  html,
  body {
    margin: 0;
    min-height: 100%;
  }

  body {
    background: var(--bg);
    color: var(--text);
    font-family: Inter, ui-sans-serif, system-ui, -apple-system,
      BlinkMacSystemFont, "Segoe UI", sans-serif;
  }

  /* APP */

  .app {
    min-height: 100vh;
    display: flex;
  }

  /* SIDEBAR */

  .sidebar {
    width: 250px;
    min-height: 100vh;
    flex-shrink: 0;
    background: #151827;
    color: white;
    padding: 28px 18px;
    display: flex;
    flex-direction: column;
  }

  .brand {
    font-size: 21px;
    font-weight: 800;
    padding: 0 12px 30px;
    letter-spacing: -.5px;
  }

  .brand span {
    color: #8d7cff;
  }

  .nav-label {
    color: #777e95;
    text-transform: uppercase;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
    padding: 0 12px 10px;
  }

  .day {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 11px 12px;
    margin-bottom: 4px;
    border-radius: 10px;
    color: #c8ccda;
  }

  .day.active {
    background: #292c40;
    color: white;
  }

  .day-count {
    margin-left: auto;
    color: #858ba0;
    font-size: 12px;
  }

  .new-list {
    margin: 18px 8px;
    padding: 12px;
    border: 1px dashed #4a4e62;
    border-radius: 10px;
    color: #b9bdd0;
    text-align: center;
  }

  .sidebar-footer {
    margin-top: auto;
    padding: 12px;
    color: #777e95;
    font-size: 12px;
  }

  /* CONTENT */

  .content {
    flex: 1;
    min-width: 0;
    padding: 34px 42px 60px;
  }

  .content-inner {
    width: 100%;
    max-width: 1000px;
    margin: 0 auto;
  }

  /* HEADER */

  .top {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    margin-bottom: 28px;
  }

  .eyebrow {
    color: var(--accent);
    font-size: 13px;
    font-weight: 800;
    letter-spacing: .3px;
    margin-bottom: 5px;
  }

  h1 {
    margin: 0;
    font-size: 31px;
    line-height: 1.15;
    letter-spacing: -1px;
  }

  .subtitle {
    color: var(--muted);
    margin-top: 6px;
  }

  .close-day {
    padding: 11px 17px;
    border-radius: 10px;
    background: var(--text);
    color: white;
    font-weight: 700;
    white-space: nowrap;
  }

  /* LIST GRID */

  .lists {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
  }

  .list {
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: 16px;
    box-shadow: var(--shadow);
    overflow: hidden;
  }

  .list-header {
    padding: 18px 20px;
    border-bottom: 1px solid var(--line);
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .list-name {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 17px;
    font-weight: 800;
  }

  .dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--accent);
  }

  .list-meta {
    color: var(--muted);
    font-size: 12px;
    margin-top: 2px;
  }

  .tasks {
    padding: 8px 20px;
  }

  .task {
    min-height: 52px;
    display: flex;
    align-items: center;
    gap: 12px;
    border-bottom: 1px solid #f0f1f5;
  }

  .task:last-child {
    border-bottom: 0;
  }

  .checkbox {
    width: 21px;
    height: 21px;
    flex-shrink: 0;
    border: 2px solid #ccd1dd;
    border-radius: 7px;
    background: white;
  }

  .task.completed .checkbox {
    background: var(--green);
    border-color: var(--green);
    position: relative;
  }

  .task.completed .checkbox::after {
    content: "✓";
    position: absolute;
    color: white;
    font-size: 13px;
    font-weight: 900;
    left: 3px;
    top: -3px;
  }

  .task.completed .task-text {
    color: #a3a9b8;
    text-decoration: line-through;
  }

  .task-text {
    flex: 1;
  }

  .delete {
    color: #c2c7d2;
    font-size: 19px;
  }

  .add-task {
    display: flex;
    gap: 8px;
    padding: 12px 20px 18px;
  }

  .input {
    flex: 1;
    min-width: 0;
    height: 40px;
    border: 1px solid var(--line);
    border-radius: 9px;
    background: white;
    color: var(--muted);
    padding: 0 12px;
    display: flex;
    align-items: center;
  }

  .add-button {
    height: 40px;
    padding: 0 14px;
    border-radius: 9px;
    background: var(--accent);
    color: white;
    font-weight: 750;
    display: flex;
    align-items: center;
  }

  /* DETAIL SCREEN */

  .detail {
    margin-top: 40px;
  }

  .detail-header {
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 24px 0;
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
  }

  .back {
    width: 42px;
    height: 42px;
    border-radius: 12px;
    border: 1px solid var(--line);
    background: white;
    display: grid;
    place-items: center;
    font-size: 21px;
  }

  .detail-title h2 {
    margin: 0;
    font-size: 27px;
    letter-spacing: -.7px;
  }

  .detail-meta {
    color: var(--muted);
    font-size: 13px;
    margin-top: 2px;
  }

  .detail-done {
    margin-left: auto;
    padding: 10px 17px;
    border-radius: 10px;
    background: var(--text);
    color: white;
    font-weight: 750;
  }

  .detail-body {
    margin-top: 22px;
  }

  .detail-task-list {
    background: white;
    border: 1px solid var(--line);
    border-radius: 14px;
    overflow: hidden;
    box-shadow: var(--shadow);
  }

  .detail-task {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 18px;
    min-height: 64px;
    border-bottom: 1px solid var(--line);
  }

  .detail-task:last-child {
    border-bottom: 0;
  }

  .detail-task .checkbox {
    width: 24px;
    height: 24px;
  }

  .detail-task-text {
    font-size: 16px;
    flex: 1;
  }

  .detail-add {
    display: flex;
    gap: 10px;
    margin-top: 16px;
  }

  .detail-input {
    flex: 1;
    height: 48px;
    padding: 0 14px;
    background: white;
    border: 1px solid var(--line);
    border-radius: 11px;
    color: var(--muted);
    display: flex;
    align-items: center;
  }

  .detail-add-button {
    height: 48px;
    padding: 0 18px;
    border-radius: 11px;
    background: var(--accent);
    color: white;
    font-weight: 750;
    display: flex;
    align-items: center;
  }

  /* FAB */

  .fab {
    position: fixed;
    right: 32px;
    bottom: 28px;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    background: var(--accent);
    color: white;
    display: grid;
    place-items: center;
    font-size: 27px;
    box-shadow: 0 10px 25px rgba(108,92,231,.35);
  }

  /* RESPONSIVE */

  @media (max-width: 850px) {
    .sidebar {
      width: 72px;
      padding: 20px 8px;
    }

    .brand {
      font-size: 0;
      text-align: center;
      padding: 5px 0 25px;
    }

    .brand span {
      font-size: 22px;
    }

    .nav-label,
    .day-label,
    .new-list,
    .sidebar-footer {
      display: none;
    }

    .day {
      justify-content: center;
    }

    .day-count {
      display: none;
    }

    .content {
      padding: 24px 18px 50px;
    }

    .lists {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 600px) {
    .top {
      align-items: flex-start;
      flex-direction: column;
      gap: 16px;
    }

    h1 {
      font-size: 27px;
    }

    .detail-header {
      gap: 12px;
    }

    .detail-title h2 {
      font-size: 22px;
    }

    .detail-done {
      font-size: 13px;
    }
  }
</style>
</head>

