  .list-name {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 17px;
    font-weight: 800;
  }

  .dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--accent);
  }

  .list-meta {
    color: var(--muted);
    font-size: 12px;
    margin-top: 2px;
  }

  .tasks {
    padding: 8px 20px;
  }

  .task {
    min-height: 52px;
    display: flex;
    align-items: center;
    gap: 12px;
    border-bottom: 1px solid #f0f1f5;
  }

  .task:last-child {
    border-bottom: 0;
  }

  .checkbox {
    width: 21px;
    height: 21px;
    flex-shrink: 0;
    border: 2px solid #ccd1dd;
    border-radius: 7px;
    background: white;
  }

  .task.completed .checkbox {
    background: var(--green);
    border-color: var(--green);
    position: relative;
  }

  .task.completed .checkbox::after {
    content: "✓";
    position: absolute;
    color: white;
    font-size: 13px;
    font-weight: 900;
    left: 3px;
    top: -3px;
  }

  .task.completed .task-text {
    color: #a3a9b8;
    text-decoration: line-through;
  }

  .task-text {
    flex: 1;
  }

  .delete {
    color: #c2c7d2;
    font-size: 19px;
  }

  .add-task {
    display: flex;
    gap: 8px;
    padding: 12px 20px 18px;
  }

  .input {
    flex: 1;
    min-width: 0;
    height: 40px;
