    border-radius: 9px;
    background: white;
    color: var(--muted);
    padding: 0 12px;
    display: flex;
    align-items: center;
  }

  .add-button {
    height: 40px;
    padding: 0 14px;
    border-radius: 9px;
    background: var(--accent);
    color: white;
    font-weight: 750;
    display: flex;
    align-items: center;
  }

