  .detail-meta {
    color: var(--muted);
    font-size: 13px;
    margin-top: 2px;
  }

  .detail-done {
    margin-left: auto;
    padding: 10px 17px;
    border-radius: 10px;
    background: var(--text);
    color: white;
    font-weight: 750;
  }

  .detail-body {
    margin-top: 22px;
  }

  .detail-task-list {
    background: white;
    border: 1px solid var(--line);
    border-radius: 14px;
    overflow: hidden;
    box-shadow: var(--shadow);
  }

  .detail-task {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 18px;
    min-height: 64px;
    border-bottom: 1px solid var(--line);
  }

  .detail-task:last-child {
    border-bottom: 0;
  }

  .detail-task .checkbox {
    width: 24px;
    height: 24px;
  }

  .detail-task-text {
    font-size: 16px;
    flex: 1;
  }

  .detail-add {
    display: flex;
    gap: 10px;
    margin-top: 16px;
  }

  .detail-input {
    flex: 1;
    height: 48px;
    padding: 0 14px;
    background: white;
    border: 1px solid var(--line);
    border-radius: 11px;
    color: var(--muted);
    display: flex;
    align-items: center;
  }

  .detail-add-button {
    height: 48px;
    padding: 0 18px;
